    ["boa-vista", "Boa Vista", [30, 12, 6, 10], "beach nature offbeat", "Saharan-style dunes, long empty beaches and nesting loggerhead turtles from July to October on Cape Verde's wildest island.", "Rent a 4x4 with other travellers to explore. Join a turtle-watch with a local conservation group."],
    ["praia-cape-verde", "Praia", [25, 10, 3, 3], "city culture", "The capital on Santiago island, with the Plateau old town, a busy market and soulful live morna music at night.", "Aluguers, the shared vans, cost a dollar or two. Visit Cidade Velha, the first colonial town in the tropics, as a day trip."],
    ["tarrafal", "Tarrafal", [20, 10, 4, 3], "beach history offbeat", "A beach town of calm sandy coves at Santiago's northern tip, with a museum in the former political prison camp.", "Aluguers from Praia take about 2 hours through the Serra Malagueta mountains, a scenic and cheap ride."],
    ["brava-island", "Brava", [20, 10, 4, 3], "offbeat trekking", "The smallest inhabited island, green and flowery, with old cobbled paths linking villages for quiet hikes.", "Ferries from Fogo are short but weather dependent, so leave spare days in your plans."]
